import sys

def is_valid_h(h):
    return 0 <= h <= 23

def is_valid_m(m):
    return 0 <= m <= 59

def generate_next_time(current_h, current_m):
    # Try increasing minute
    if current_m < 59:
        if is_valid_h(current_h) and is_valid_m(current_m + 1):
            return (current_h, current_m + 1)

    # If minute overflows, reset minute and try increasing hour
    if current_h < 23:
        if is_valid_h(current_h + 1) and is_valid_m(0):
            return (current_h + 1, 0)

    # If hour overflows, reset hour (which implies minute must be 0 to be valid in next cycle)
    if current_h == 23 and current_m == 59:
        if is_valid_h(0) and is_valid_m(0):
            return (0, 0)

    return None

def parse_time(s):
    h = int(s[:2])
    m = int(s[3:])
    return h, m

def format_time(h, m):
    return f"{h:02d}:{m:02d}"

def solve():
    lines = sys.stdin.read().splitlines()
    if not lines:
        return
    start_str = lines[0].strip()
    end_str = lines[1].strip()

    start_h, start_m = parse_time(start_str)
    end_h, end_m = parse_time(end_str)

    current_h, current_m = start_h, start_m
    result = []

    # Add start time
    result.append((current_h, current_m))

    # Simulate step by step until we reach the end time
    while True:
        next_time = generate_next_time(current_h, current_m)
        if next_time is None:
            break
        current_h, current_m = next_time
        result.append((current_h, current_m))

        if current_h == end_h and current_m == end_m:
            break

    # Output results
    print(len(result))
    for h, m in result:
        print(format_time(h, m))

if __name__ == "__main__":
    solve()

import sys

def get_valid_next(hour, minute):
    # Try increasing hour
    next_h = (hour + 1) % 24
    if next_h < 24:
        return next_h, minute
    return -1, -1

def get_valid_prev(hour, minute):
    # Try decreasing hour
    prev_h = (hour - 1) % 24
    if prev_h < 24:
        return prev_h, minute
    return -1, -1

def get_valid_next_min(hour, minute):
    next_m = (minute + 1) % 60
    if next_m < 60:
        return hour, next_m
    return -1, -1

def get_valid_prev_min(hour, minute):
    prev_m = (minute - 1) % 60
    if prev_m < 60:
        return hour, prev_m
    return -1, -1

def can_reach(start_h, start_m, target_h, target_m):
    # BFS to find shortest path from start to target
    # State: (h, m)
    queue = [(start_h, start_m)]
    visited = {(start_h, start_m)}

    while queue:
        h, m = queue.pop(0)
        if h == target_h and m == target_m:
            return True

        # Try all 4 moves
        moves = [
            (get_valid_next(h, m)),
            (get_valid_prev(h, m)),
            (get_valid_next_min(h, m)),
            (get_valid_prev_min(h, m))
        ]

        for next_h, next_m in moves:
            if next_h == -1:
                continue
            if (next_h, next_m) not in visited:
                visited.add((next_h, next_m))
                queue.append((next_h, next_m))

    return False

def count_times(start_s, target_s):
    # Parse start and target
    sh, sm = map(int, start_s.split(':'))
    th, tm = map(int, target_s.split(':'))

    # If already same, only one time
    if sh == th and sm == tm:
        return [start_s]

    # BFS to find all reachable times that lie on a shortest path
    # Actually, the problem asks for all times seen when setting correctly optimally.
    # This implies we need to find all nodes that are part of ANY shortest path from start to target.

    # First, compute shortest distance from start to all nodes
    dist_from_start = {}
    queue = [(sh, sm, 0)]
    dist_from_start[(sh, sm)] = 0

    while queue:
        h, m, d = queue.pop(0)
        if h == th and m == tm:
            continue

        moves = [
            get_valid_next(h, m),
            get_valid_prev(h, m),
            get_valid_next_min(h, m),
            get_valid_prev_min(h, m)
        ]

        for nh, nm in moves:
            if nh == -1:
                continue
            if (nh, nm) not in dist_from_start:
                dist_from_start[(nh, nm)] = d + 1
                queue.append((nh, nm, d + 1))

    total_dist = dist_from_start[(th, tm)]

    # Now compute shortest distance from all nodes to target
    dist_to_target = {}
    queue = [(th, tm, 0)]
    dist_to_target[(th, tm)] = 0

    while queue:
        h, m, d = queue.pop(0)

        moves = [
            get_valid_next(h, m),
            get_valid_prev(h, m),
            get_valid_next_min(h, m),
            get_valid_prev_min(h, m)
        ]

        for nh, nm in moves:
            if nh == -1:
                continue
            if (nh, nm) not in dist_to_target:
                dist_to_target[(nh, nm)] = d + 1
                queue.append((nh, nm, d + 1))

    # Collect all times on shortest paths
    # A node u is on a shortest path if dist_start[u] + dist_target[u] == total_dist
    result = []
    for (h, m), d_start in dist_from_start.items():
        if (h, m) in dist_to_target:
            d_target = dist_to_target[(h, m)]
            if d_start + d_target == total_dist:
                result.append(f"{h:02d}:{m:02d}")

    return result

