        h = (h + 1) % 24
        m = 0
        if h <= 23:
            candidates = [f"{h:02d}:{m:02d}"]

    # Try decreasing minutes
    for _ in range(2):
        m = (m - 1) % 60
        if h <= 23 and m <= 59:
            candidates.append(f"{h:02d}:{m:02d}")
        else:
            # Minutes are invalid, try to decrement hour
            h = (h - 1) % 24
            if h <= 23:
                candidates.append(f"{h:02d}:{m:02d}")
            else:
                break

    # If we couldn't find a valid time by just decrementing minutes, try the previous hour
    if not candidates:
        h = (h - 1) % 24
        m = 59
        if h <= 23:
            candidates = [f"{h:02d}:{m:02d}"]

    # Try increasing hours
    for _ in range(2):
        h = (h + 1) % 24
        m = 0
        if h <= 23 and m <= 59:
            candidates.append(f"{h:02d}:{m:02d}")
        else:
            break

    # Try decreasing hours
    for _ in range(2):
        h = (h - 1) % 24
        m = 59
        if h <= 23 and m <= 59:
            candidates.append(f"{h:02d}:{m:02d}")
        else:
            break

    return candidates

