import sys

def get_valid_next(hours, minutes):
    # Try incrementing minutes first
    if minutes < 59:
        return hours, minutes + 1
    else:
        # Increment hours
        if hours < 23:
            return hours + 1, 0
        else:
            # Wrap around to 00:00
            return 0, 0

def get_valid_prev(hours, minutes):
    # Try decrementing minutes first
    if minutes > 0:
        return hours, minutes - 1
    else:
        # Decrement hours
        if hours > 0:
            return hours - 1, 59
        else:
            # Wrap around to 23:59
            return 23, 59

def solve():
    input_data = sys.stdin.read().strip().split('\n')
    current_time_str = input_data[0].strip()
    target_time_str = input_data[1].strip()

    def parse_time(t):
        h = int(t[:2])
        m = int(t[3:])
        return h, m

    current_h, current_m = parse_time(current_time_str)
    target_h, target_m = parse_time(target_time_str)

    path = []
    path.append((current_h, current_m))

    while (current_h, current_m) != (target_h, target_m):
        next_state = get_valid_next(current_h, current_m)
        if next_state == (target_h, target_m):
            path.append(next_state)
            current_h, current_m = next_state
        else:
            break

    # If we haven't reached the target, try going backwards
    if (current_h, current_m) != (target_h, target_m):
        path = []
        path.append((current_h, current_m))
        while (current_h, current_m) != (target_h, target_m):
            prev_state = get_valid_prev(current_h, current_m)
            if prev_state == (target_h, target_m):
                path.append(prev_state)
                current_h, current_m = prev_state
            else:
                break

    # Format output
    result = []
    for h, m in path:
        result.append(f"{h:02d}:{m:02d}")

    print(len(result))
    for time_str in result:
        print(time_str)

if __name__ == "__main__":
